            # Periodically recompute saturation from scratch to correct drift
            if iteration % 20 == 0 and n > 20:
                saturated = [set() for _ in range(n)]
                for u in range(n):
                    if color[u] != -1:
                        for v in neighbors[u]:
                            if color[v] == -1:
                                saturated[v].add(color[u])
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph, then random
            v = max(uncolored, key=lambda x: (
                len(saturated[x]),
                sum(1 for u in neighbors[x] if u in uncolored),
                random.random()
            ))
            used = [False] * n
            for u in neighbors[v]:
                c = color[u]
                if c != -1:
                    used[c] = True
            c = 0
            while used[c]:
                c += 1
            color[v] = c
            uncolored.remove(v)
            for u in neighbors[v]:
                if u in uncolored:
                    saturated[u].add(c)
        return color

    # Helper: Maximal Independent Set extraction with weighted degree heuristic
    def mis_based():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Compute dynamic weights: degree in uncolored subgraph + saturation estimate
            weights = [0] * n
            for v in uncolored:
                deg_in_uncolored = sum(1 for u in neighbors[v] if u in uncolored)
                # Estimate saturation: number of colors in neighborhood (approximate)
                sat_est = 0
                for u in neighbors[v]:
                    if color[u] != -1:
                        sat_est += 1  # Overestimate, but fast
                weights[v] = deg_in_uncolored + sat_est * 0.1
            # Start MIS with vertex of max weight
            v = max(uncolored, key=lambda x: weights[x])
            S = {v}
            U = set()
            W = set()
            for u in uncolored:
                if u == v:
                    continue
                if any(u in neighbors[w] for w in S):
                    W.add(u)
                else:
                    U.add(u)
            while U:
                # Select u in U with max (weight + |N(u) ∩ W|), tie-break by min degree in G[U]
                u = max(U, key=lambda x: (
                    weights[x] + sum(1 for nb in neighbors[x] if nb in W),
                    -sum(1 for nb in neighbors[x] if nb in U),
                    random.random()
                ))
                S.add(u)
                U.remove(u)
                for nb in neighbors[u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
            for v in S:
                color[v] = c
            uncolored -= S
            c += 1
        return color

    # Run multiple heuristics
    candidates = [
        welsh_powell(),
        smallest_last(),
        dsatur(),
        rlf(),
        adaptive_dsatur(),
        mis_based()
    ]

    # Select best candidate (fewest colors)
    best_coloring = None
    best_num_colors = float('inf')
    for col in candidates:
        num_colors = max(col) + 1 if n > 0 else 0
        if num_colors < best_num_colors:
            best_num_colors = num_colors
            best_coloring = col

    # Refine with Kempe chains
    refined = kempe_refine(best_coloring)
    num_colors_refined = max(refined) + 1 if n > 0 else 0
    if num_colors_refined < best_num_colors:
        return refined
    else:
        return best_coloring
